package com.podhod.app;
import android.app.*;import android.content.*;import android.widget.*;import org.json.*;
final class WalkPanel {
 final MainActivity a;final LinearLayout card,history;final WalkMap map;final TextView status,summary,button;String lastHistory="";
 WalkPanel(MainActivity a){this.a=a;card=a.card(a.body);card.addView(a.title(Lang.t("Прогулка"),24));a.space(card,8);status=a.text("",14,a.MUTED);card.addView(status);a.space(card,12);map=new WalkMap(a);card.addView(map,new LinearLayout.LayoutParams(-1,a.dp(230)));mapTools(a,card,map);summary=a.title("",22);card.addView(summary);button=a.button(card,Lang.t("Начать прогулку"),true,()->{if(WalkService.running){a.startService(new Intent(a,WalkService.class).setAction("stop"));}else a.startWalk();a.stepHandler.postDelayed(()->{if(a.stepsView!=null)a.stepsView.refresh();},500);});
  a.hint(card,Lang.t("О карте и записи"),Lang.t("GPS записывается только во время прогулки. Карта OpenStreetMap загружается через интернет; сервер карты получает запросы участков карты. Маршруты хранятся на телефоне и входят в полную копию. Без сети линия маршрута сохраняется, но фон карты может быть недоступен. В помещении GPS может не найти точку. Ограничение записи — 24 часа."));
  history=a.column();card.addView(history);refresh();
 }
 static void mapTools(MainActivity a,LinearLayout box,WalkMap map){LinearLayout row=new LinearLayout(a);box.addView(row);TextView minus=a.text("−",24,a.GREEN),plus=a.text("+",24,a.GREEN),fit=a.text(Lang.t("Весь маршрут"),13,a.GREEN);for(TextView b:new TextView[]{minus,plus,fit}){b.setGravity(android.view.Gravity.CENTER);row.addView(b,new LinearLayout.LayoutParams(0,a.dp(48),1));}a.clickable(minus,()->map.zoom(-1));a.clickable(plus,()->map.zoom(1));a.clickable(fit,()->{map.zoomOffset=0;map.panX=map.panY=0;map.invalidate();});a.link(box,"© OpenStreetMap contributors",()->a.startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse("https://www.openstreetmap.org/copyright"))));}
 void refresh(){JSONObject data=Walks.data(a),active=data.optJSONObject("active");JSONArray list=data.optJSONArray("history");JSONObject shown=active!=null?active:list.optJSONObject(list.length()-1);map.route(shown);summary.setText(shown==null?"0.00"+Lang.t(" км"):Walks.summary(shown));boolean running=WalkService.running;
  status.setText(running?(active==null||active.optJSONArray("points").length()==0?Lang.t("Ищем GPS…"):System.currentTimeMillis()-active.optLong("lastFix")>120000?Lang.t("Нет свежего сигнала GPS"):Lang.t("Запись прогулки")):active!=null?Lang.t("Запись прервана. Начни новую прогулку."):shown!=null?Lang.t("Последняя прогулка"):Lang.t("Нажми начать и бери телефон с собой"));button.setText(Lang.t(running?"Завершить прогулку":"Начать прогулку"));
  String signature=list.length()+":"+(list.length()==0?"":list.optJSONObject(list.length()-1).optString("id"));if(!signature.equals(lastHistory)){lastHistory=signature;history.removeAllViews();if(list.length()>0){a.space(history,16);a.label(history,Lang.t("История прогулок"));}for(int i=list.length()-1;i>=0;i--){JSONObject walk=list.optJSONObject(i);String date=new java.text.SimpleDateFormat("d MMM · HH:mm",Lang.locale()).format(new java.util.Date(walk.optLong("started")));a.link(history,date+" · "+Walks.summary(walk),()->detail(walk));}}
 }
 void detail(JSONObject walk){LinearLayout box=a.form();box.addView(a.title(Walks.summary(walk),22));WalkMap view=new WalkMap(a);view.route(walk);box.addView(view,new LinearLayout.LayoutParams(-1,a.dp(280)));mapTools(a,box,view);if(walk.optBoolean("interrupted"))box.addView(a.text(Lang.t("Запись была прервана"),14,a.MUTED));a.panel(Lang.t("Карта прогулки"),box,Lang.t("Закрыть"),()->{},false);}
}
